function invocationsPerHour(minuteField) {
  if (minuteField === '*') return 60;
  if (minuteField.startsWith('*/')) {
    const step = parseInt(minuteField.slice(2), 10);
    let count = 0;
    for (let m = 0; m < 60; m += step) count++;
    return count;
  }
  return minuteField.split(',').length;
}

