export function aggregateUsageRows(rows, period) {
  const byKey = new Map();
  for (const r of rows) {
    const key = `${r.task_type} ${r.model_id}`;
    const line = byKey.get(key) ?? { calls: 0, amountUsd: 0 };
    line.calls += 1;
    line.amountUsd += Number(r.cost_usd ?? 0);
    byKey.set(key, line);
  }
  return [...byKey.values()];
}
